const testing = std.testing;

test "accessors land at the offsets the C macros used" {
    const base = @intFromPtr(&g_ram[0]);
    try testing.expectEqual(@as(usize, 131072), g_ram.len);
    try testing.expectEqual(@as(usize, 0x10), @intFromPtr(main_module_index) - base);
    try testing.expectEqual(@as(usize, 0x20), @intFromPtr(link_y_coord) - base);
    try testing.expectEqual(@as(usize, 0x22), @intFromPtr(link_x_coord) - base);
    try testing.expectEqual(@as(usize, 0x51), @intFromPtr(tiledetect_which_y_pos) - base);
    try testing.expectEqual(@as(usize, 0xAE), @intFromPtr(dung_hdr_tag) - base);
    try testing.expectEqual(@as(usize, 0x800), @intFromPtr(oam_buf) - base);
    try testing.expectEqual(@as(usize, 0x600), @intFromPtr(room_bounds_y) - base);
    try testing.expectEqual(@as(usize, 0x1000), @intFromPtr(uvram) - base);
}

test "writing through an accessor is visible in the flat ram array" {
    @memset(g_ram[0..0x100], 0);
    link_y_coord.* = 0x1234;
    // Little endian, and the two bytes sit at 0x20 and 0x21.
    try testing.expectEqual(@as(u8, 0x34), g_ram[0x20]);
    try testing.expectEqual(@as(u8, 0x12), g_ram[0x21]);

    main_module_index.* = 7;
    try testing.expectEqual(@as(u8, 7), g_ram[0x10]);

    dung_hdr_tag[2] = 0x99;
    try testing.expectEqual(@as(u8, 0x99), g_ram[0xAE + 2]);

    // An odd-addressed 16-bit view really is unaligned.
    tiledetect_which_y_pos[0] = 0xbeef;
    try testing.expectEqual(@as(u8, 0xef), g_ram[0x51]);
    try testing.expectEqual(@as(u8, 0xbe), g_ram[0x52]);
}

test "overlapping views agree, as they do in the C" {
    @memset(g_ram[0x600..0x620], 0);
    // ow_scroll_vars0 and room_bounds_y are the same eight bytes.
    ow_scroll_vars0.ystart = 0x1111;
    try testing.expectEqual(@as(u16, 0x1111), room_bounds_y.v[0]);
    room_bounds_y.v[3] = 0x2222;
    try testing.expectEqual(@as(u16, 0x2222), ow_scroll_vars0.xend);
}

test "struct layouts match the C definitions" {
    try testing.expectEqual(4, @sizeOf(MovableBlockData));
    try testing.expectEqual(4, @sizeOf(OamEnt));
    try testing.expectEqual(4, @sizeOf(OamEntSigned));
    try testing.expectEqual(8, @sizeOf(RoomBounds));
    try testing.expectEqual(8, @sizeOf(OwScrollVars));
    try testing.expectEqual(28, @sizeOf(MirrorHdmaVars));
    try testing.expectEqual(64, @sizeOf(UploadVram_Row));
    try testing.expectEqual(2048, @sizeOf(UploadVram_32x32));
    try testing.expectEqual(264, @sizeOf(UploadVram_3));
}
